// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address depositor, address other, uint256 amt) public {
        amt = bound(amt, 0, 1 ether);
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));

        vm.deal(depositor, amt);
        vm.deal(other, 1 ether);

        if (amt > 0) {
            vm.startPrank(depositor);
            c.addToBalance{value: amt}();
            vm.stopPrank();
        }

        uint256 amt2 = 1 ether;
        vm.startPrank(other);
        c.addToBalance{value: amt2}();
        vm.stopPrank();

        uint256 balSum = c.getBalance(depositor) + c.getBalance(other);
        assertTrue(address(c).balance == balSum);
    }
}
